ed from name/blurb/hook","si_all":["Winter / Ski","ski"],"shelf_fit":{"Winter / Ski":"evidenced","family":"destination","hiking":"destination","romance":"destination","ski":"primary"},"commission_pct_low":10,"commission_pct_high":20,"commission_lane":["operator","DMC"],"commission_embedded":true,"commission_basis":"band+lane","si_raw":"Winter / Ski","si_map_basis":"normalised from free text ''Winter / Ski'' by gen_normalise_jewel_si"},{"name":"Ski the last great ski town","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"~USD 130-239/day lift","timing":"ski ~late Nov-early Apr — book peak 4-8 mo ahead","draw_rank":2,"hook":"an unpretentious, uncrowded Vail Resorts mountain over a Victorian town that never sold out — varied terrain, real character, Epic Pass access","si":"ski","blurb":"an unpretentious, uncrowded Vail Resorts mountain over a Victorian town that never sold out — varied terrain, real character, Epic Pass access","when":"ski ~late Nov-early Apr — book peak 4-8 mo ahead","commission":"DMC/ski-op 10-20% (embedded-capable)","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Winter / Ski","ski"],"shelf_fit":{"Winter / Ski":"evidenced","family":"destination","hiking":"destination","romance":"destination","ski":"primary"},"commission_pct_low":10,"commission_pct_high":20,"commission_lane":["operator","DMC"],"commission_embedded":true,"commission_basis":"band+lane","si_raw":"Winter / Ski","si_map_basis":"normalised from free text ''Winter / Ski'' by gen_normalise_jewel_si"},{"name":"A private cat-ski day at Scarp Ridge (Eleven)","si_tag":"Winter / Ski","status":"future","tier":"ultra","price_band":"on application (private-lodge/cat program)","timing":"winter, avalanche-gated; guide + beacon/probe/shovel","draw_rank":3,"hook":"exclusive private cat-skiing on ~1,000 acres of untracked terrain above Crested Butte with Eleven Experience — the top-end powder day","si":"ski","blurb":"exclusive private cat-skii