  ('crystal-mountain-washington', '12A', 'Crystal Mountain', 'United States', 'Washington''s biggest mountain, under the full face of Mt', 'live', 'verified', 'northernLights', 'Pacific Northwest', '{"ski","culinary","romance","family","ultra"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Washington''s LARGEST ski resort — 2,600 total acres (~2,300 lift-served), 80+ named runs, 10 lifts (~19,888 riders/hr)","Base ~4,400 ft, Silver King summit ~7,002 ft, ~3,100 ft vertical (lower than Rockies/Sierra — AMS de-emphasized)","Managed by Alterra Mountain Company (acquired 2018); on the Ikon Pass (up to 7 days — verify current terms)","Mt. Rainier Gondola (Doppelmayr 8-seat) first ran New Year''s Day 2011; ~2,400 vert to the Summit House (6,872 ft) = Washington''s HIGHEST-elevation restaurant","Unobstructed view of Mt. Rainier — 14,410-ft active glaciated stratovolcano, highest peak in the Cascades, <13 mi WSW","On-mountain lodging limited (Crystal Mountain Hotels: Alpine Inn / Village Inn / Quicksilver); most beds Greenwater/Enumclaw/Seattle","Access via SR-410 (winters hard — chains, closures; 2025/26 opened late 20 Dec after storm damage); SEA gateway ~76 mi"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide); ski patrol on-mountain; backcountry via Pierce County SAR / 911","hospital":"nearest ER St. Elizabeth (Enumclaw) + MultiCare Auburn Medical Center (24/7 ER, ~45-60 min down SR-410); major trauma to Harborview (Seattle, Level I), by air when needed","malaria":"none","yellow_fever":"not required","activity_note":"AVALANCHE beyond ropes (heavy maritime ''Cascade Concrete''; check NWAC nwac.us, guide + beacon/probe/shovel); TREE WELLS + deep snow (acute Cascade hazard — heightened, ride with partner); Cascade winter driving + SR-410 chain control/closures (check WSDOT); cold + fast Pacific storms + whiteouts (gondola/upper lifts wind-hold); volcanic/glaciated alpine setting (Mt. Rainier scenery + serious off-resort terrain); AMS brief note only (summit ~7,002 ft)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-08-20T14:47:42Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) ski + big-storm powder cycles; weekends busiest (Seattle catchment); summer Jul-Aug (gondola + Rainier view)","shoulder":"early season (late Nov-mid Dec), Jan weekdays, late Mar-Apr spring skiing, September (clear-view shoulder)","green":"May-mid Jun + Oct-mid Nov (between-season lulls; some closures — verify)","booking_lead":"Christmas/NY + limited on-mountain rooms (Alpine Inn/Village Inn) 4-9 mo; Presidents''/Feb 3-6 mo; Summit House dinner weeks-months; summer gondola weeks; shoulder/powder 1-6 wk","off_season_specials":"spring-ski + Summit House packages (late Mar-Apr); Sep clear-view gondola breaks; early-season pre-Christmas ski; summer gondola + Rainier view as shoulder engine; midweek powder-chase deals","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, spring closing wknd, summer weekends + Jul 4 gondola (verify 2027)","fire_date":"FIRE ski mid-late Mar (ahead of Apr-Jun early-bird) + late Aug-early Sep (ahead of Sep-Nov fall wave); market summer gondola/Rainier view by Jan-Feb"},"jewels":[{"name":"Ski Washington''s largest mountain — 2,600 acres, top to bottom","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"~USD 99-189/day lift; package better value","timing":"ski late Nov/Dec-Apr, snow-dependent; in-bounds patrolled","draw_rank":1,"si":"ski","when":"ski late Nov/Dec-Apr, snow-dependent; in-bounds patrolled","commission":"DMC/ski-op 10-20% (embedded-capable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Winter / 